description:
A bar of menus for an app's top-level commands (File / Edit / View …).

  Menubar(aria_label: "Application") do
    MenubarMenu do
      MenubarTrigger { "File" }
      MenubarContent do
        MenubarItem { "New file" }
        MenubarSub do
          MenubarSubTrigger { "Open recent" }
          MenubarSubContent { MenubarItem { "project-alpha" } }
        end
        MenubarSeparator()
        MenubarItem { "Save" }
      end
    end
  end

The bar shares `variant:`, `size:` and `orientation:` with every menu. Behaviour (opening, hover-switching, submenus, keyboard navigation, typeahead, checkbox/radio state) lives in the `ui--menubar` Stimulus controller.

examples.code:
phlex do
  Menubar(variant:, size:, aria_label: "Application") do
    MenubarMenu do
      MenubarTrigger { "File" }
      MenubarContent do
        MenubarItem { plain "New file"; Kbd(size: :sm, class: "ms-auto") { "⌘N" } }
        MenubarItem { plain "Open…"; Kbd(size: :sm, class: "ms-auto") { "⌘O" } }
        MenubarSub do
          MenubarSubTrigger { "Open recent" }
          MenubarSubContent do
            MenubarItem { "project-alpha" }
            MenubarItem { "landing-page" }
            MenubarItem { "design-system" }
          end
        end
        MenubarSeparator()
        MenubarItem { plain "Save"; Kbd(size: :sm, class: "ms-auto") { "⌘S" } }
        MenubarItem { plain "Save as…"; Kbd(size: :sm, class: "ms-auto") { "⇧⌘S" } }
      end
    end
    MenubarMenu do
      MenubarTrigger { "Edit" }
      MenubarContent do
        MenubarItem { plain "Undo"; Kbd(size: :sm, class: "ms-auto") { "⌘Z" } }
        MenubarItem { plain "Redo"; Kbd(size: :sm, class: "ms-auto") { "⇧⌘Z" } }
        MenubarSeparator()
        MenubarItem { "Cut" }
        MenubarItem { "Copy" }
        MenubarItem { "Paste" }
      end
    end
    MenubarMenu do
      MenubarTrigger { "View" }
      MenubarContent do
        MenubarItem { "Zoom in" }
        MenubarItem { "Zoom out" }
        MenubarItem { "Reset zoom" }
        MenubarSeparator()
        MenubarItem(disabled: true) { "Enter full screen" }
      end
    end
  end
end

